import type { Model } from './models.ts'
import { isSingleFile, modelsModuleId } from './models.ts'
import { onnxRuntimeModuleId } from './onnx-runtime.ts'

// The types of the build's virtual modules, for `src/virtual-modules.d.ts`:
// the model ids come from models.json, so a model the list does not name
// fails the type check.
const union = (ids: ReadonlyArray<string>): string =>
  ids.length === 0 ? 'never' : ids.map(id => `'${id}'`).join(' | ')

export const virtualModuleTypes = (models: ReadonlyArray<Model>): string =>
  [
    '// Generated by `npm run generate` from models.json. Do not edit.',
    '',
    "// Each model's directory on the app's own origin, ending in `/`, and",
    '// the URL of each model of one file, from the build.',
    `declare module '${modelsModuleId}' {`,
    `  export type ModelId = ${union(models.map(model => model.id))}`,
    `  export type SingleFileModelId = ${union(models.filter(isSingleFile).map(model => model.id))}`,
    '  export const modelDirectories: Readonly<Record<ModelId, string>>',
    '  export const modelUrls: Readonly<Record<SingleFileModelId, string>>',
    '}',
    '',
    "// The directory, on the app's own origin, that holds ONNX Runtime's WebAssembly.",
    `declare module '${onnxRuntimeModuleId}' {`,
    '  export const onnxRuntimeWasmPaths: string',
    '}',
    '',
  ].join('\n')
